import {
  OlapTable,
  Stream,
  IngestApi,
  MaterializedView,
  Api,
  LowCardinality,
  ClickHouseDefault,
  sql
} from "@514labs/moose-lib";

// Product Event Data Model
// Per ClickHouse best practices: order fields by cardinality (low→high)
export interface ProductEvent {
  event_type: string & LowCardinality;  // 3 values: view, cart, purchase - lowest cardinality
  event_ts: Date;                       // Time dimension for filtering
  user_id: string;                      // Medium cardinality
  product_id: string;                   // Medium cardinality
  event_id: string;                     // Unique per event - highest cardinality
  price: number & ClickHouseDefault<"NULL">;  // Only present for purchases, nullable with default
}

