  event_id: string;                     // Unique per event - highest cardinality
  price: number & ClickHouseDefault<"NULL">;  // Only present for purchases, nullable with default
}

// Ingestion Pipeline Components
// ClickHouse table - persistent storage
export const ProductEventTable = new OlapTable<ProductEvent>("ProductEvent", {
  orderByFields: ["event_type", "event_ts", "user_id", "product_id", "event_id"]
});

// Redpanda stream - buffer between ingest and ClickHouse
export const ProductEventStream = new Stream<ProductEvent>("ProductEvent", {
  destination: ProductEventTable
});

// HTTP ingest endpoint - POST /ingest/ProductEvent
export const ProductEventIngest = new IngestApi<ProductEvent>("ProductEvent", {
  destination: ProductEventStream
});

