// API Endpoints
interface TopProductsInput {
  limit?: number;
  sort_by?: string; // 'revenue' | 'purchases' | 'views' | 'carts'
}

// Top Products API - GET /api/top-products
export const topProductsApi = new Api<TopProductsInput, TopProductsRow>(
  "top-products",
  async ({ limit = 10, sort_by = 'revenue' }, { client, sql }) => {
    const orderField = sort_by === 'revenue' ? 'total_revenue' :
                       sort_by === 'purchases' ? 'purchase_count' :
                       sort_by === 'views' ? 'view_count' :
                       sort_by === 'carts' ? 'cart_count' : 'total_revenue';

    const result = await client.query.execute(sql`
      SELECT product_id, view_count, cart_count, purchase_count, total_revenue
      FROM TopProducts
      ORDER BY ${orderField} DESC
      LIMIT ${limit}
    `);
    return (await result.json()) as TopProductsRow[];
  }
);

