// Conversion Funnel API - GET /api/conversion-funnel
export const conversionFunnelApi = new Api<ConversionFunnelInput, ConversionFunnelRow>(
  "conversion-funnel",
  async ({}, { client, sql }) => {
    const result = await client.query.execute(sql`
      SELECT funnel_step, unique_users, total_events
      FROM ConversionFunnel
      ORDER BY
        CASE funnel_step
          WHEN 'view' THEN 1
          WHEN 'cart' THEN 2
          WHEN 'purchase' THEN 3
          ELSE 4
        END
    `);
    return (await result.json()) as ConversionFunnelRow[];
  }
);

