  start_hour?: string;
  end_hour?: string;
  event_type?: string;
}

// Hourly Activity API - GET /api/hourly-activity
export const hourlyActivityApi = new Api<HourlyActivityInput, HourlyActivityRow>(
  "hourly-activity",
  async ({ start_hour, end_hour, event_type }, { client, sql }) => {
    let whereClause = "";
    if (start_hour || end_hour || event_type) {
      const conditions = [];
      if (start_hour) conditions.push(sql`hour >= parseDateTimeBestEffort('${start_hour}')`);
      if (end_hour) conditions.push(sql`hour <= parseDateTimeBestEffort('${end_hour}')`);
      if (event_type) conditions.push(sql`event_type = '${event_type}'`);
      whereClause = `WHERE ${conditions.join(' AND ')}`;
    }

    const result = await client.query.execute(sql`
      SELECT hour, event_type, event_count
      FROM HourlyActivity
      ${whereClause}
      ORDER BY hour ASC, event_type ASC
    `);
    return (await result.json()) as HourlyActivityRow[];
  }
);

