#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

async function loadEvents() {
  const eventsDir = '/data/events';
  const ingestUrl = 'http://localhost:4000/ingest/ProductEvent';

  // Read all event files
  const files = fs.readdirSync(eventsDir).filter(f => f.endsWith('.json')).sort();

  console.log(`Loading ${files.length} events...`);

  for (const file of files) {
    const filePath = path.join(eventsDir, file);
    const rawEvent = JSON.parse(fs.readFileSync(filePath, 'utf8'));

    // Transform to ProductEvent format
    const productEvent = {
      event_type: rawEvent.event_type,
      event_ts: rawEvent.event_ts,
      user_id: rawEvent.user_id,
      product_id: rawEvent.product_id,
      event_id: rawEvent.event_id,
      // Extract price from properties for purchases, null otherwise
      price: rawEvent.event_type === 'purchase' ? (rawEvent.properties.price || null) : null
    };

    try {
      const response = await fetch(ingestUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(productEvent)
      });

      if (!response.ok) {
        console.error(`Failed to load ${file}: ${response.status} ${response.statusText}`);
        const text = await response.text();
        console.error('Response:', text);
      } else {
        console.log(`✓ Loaded ${file} - ${productEvent.event_type} event`);
      }
    } catch (error) {
      console.error(`Error loading ${file}:`, error.message);
    }

    // Small delay to avoid overwhelming the API
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  console.log('Finished loading events!');
}

// Check if fetch is available, if not use node-fetch equivalent
if (typeof fetch === 'undefined') {
  // Simple fetch implementation for Node.js
  global.fetch = async (url, options) => {
    const https = require('https');
    const http = require('http');
    const urlLib = require('url');

    return new Promise((resolve, reject) => {
      const parsedUrl = urlLib.parse(url);
      const lib = parsedUrl.protocol === 'https:' ? https : http;

      const req = lib.request({
        hostname: parsedUrl.hostname,
        port: parsedUrl.port,
        path: parsedUrl.path,
        method: options.method || 'GET',
        headers: options.headers
      }, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          resolve({
            ok: res.statusCode >= 200 && res.statusCode < 300,
            status: res.statusCode,
            statusText: res.statusMessage,
            text: async () => data,
            json: async () => JSON.parse(data)
          });
        });
      });

      req.on('error', reject);

      if (options.body) {
        req.write(options.body);
      }

      req.end();
    });
  };
}

loadEvents().catch(console.error);

